# 44 Modern RP phonemes with articulatory mechanics.
# vowel chart: x 0 (front) → 1 (back), y 0 (close) → 1 (open)
def V(sym, kw, ex, desc, mech, x, y, interf=None):
    return {'symbol': sym, 'kind': 'vowel', 'keyword': kw, 'examples': ex, 'description': desc, 'mechanics': mech, 'chart': {'x': x, 'y': y}, **({'interference': interf} if interf else {})}
def Cn(sym, kw, ex, desc, mech, place, manner, voiced, interf=None):
    return {'symbol': sym, 'kind': 'consonant', 'keyword': kw, 'examples': ex, 'description': desc, 'mechanics': mech, 'chart': {'place': place, 'manner': manner, 'voiced': voiced}, **({'interference': interf} if interf else {})}

